// VULNERABLE: AES-CBC without authentication
const encrypted = await crypto.subtle.encrypt(
  { name: 'AES-CBC', iv },
  key,
  data
);

// SECURE: Use AES-GCM for authenticated encryption
const iv = crypto.getRandomValues(new Uint8Array(12));
const encrypted = await crypto.subtle.encrypt(
  { name: 'AES-GCM', iv, tagLength: 128 },
  key,
  data
);

// SECURE: PBKDF2 with sufficient iterations
const keyMaterial = await crypto.subtle.importKey(
  'raw',
  new TextEncoder().encode(password),
  { name: 'PBKDF2' },
  false,
  ['deriveKey']
);
const key = await crypto.subtle.deriveKey(
  {
    name: 'PBKDF2',
    salt: crypto.getRandomValues(new Uint8Array(16)),
    iterations: 600000,  // OWASP recommended minimum
    hash: 'SHA-256'
  },
  keyMaterial,
  { name: 'AES-GCM', length: 256 },
  false,         // non-extractable
  ['encrypt', 'decrypt']
);

// SECURE: Non-extractable keys for signing
const keyPair = await crypto.subtle.generateKey(
  { name: 'ECDSA', namedCurve: 'P-384' },
  false,         // non-extractable
  ['sign', 'verify']
);
```

Use password_hash() with PASSWORD_ARGON2ID or PASSWORD_BCRYPT:

```php
// VULNERABLE: MD5 password hashing
$hash = md5($password);
$sql = "INSERT INTO users (password) VALUES ('$hash')";

// SECURE: password_hash with Argon2id (PHP 7.3+)
$hash = password_hash($password, PASSWORD_ARGON2ID, [
    'memory_cost' => 65536,
    'time_cost' => 4,
    'threads' => 3,
]);

// SECURE: password_hash with bcrypt
$hash = password_hash($password, PASSWORD_BCRYPT, [
    'cost' => 12,
]);

// SECURE: Verify password
if (password_verify($password, $storedHash)) {
    // Password is correct
    // Check if rehash is needed
    if (password_needs_rehash($storedHash, PASSWORD_ARGON2ID)) {
        $newHash = password_hash($password, PASSWORD_ARGON2ID);
        // Update hash in database
    }
}
```

