Validate redirect URLs in middleware:

```javascript
import { NextResponse } from 'next/server';

const ALLOWED_HOSTS = ['example.com', 'app.example.com'];

export function middleware(request) {
  const redirectUrl = request.nextUrl.searchParams.get('redirect');

  if (redirectUrl) {
    try {
      const url = new URL(redirectUrl, request.nextUrl.origin);
      // Only allow same-origin or whitelisted redirects
      if (!ALLOWED_HOSTS.includes(url.hostname)) {
        return NextResponse.redirect(new URL('/', request.url));
      }
      // Prevent protocol-relative URL bypass
      if (redirectUrl.startsWith('//')) {
        return NextResponse.redirect(new URL('/', request.url));
      }
      return NextResponse.redirect(url);
    } catch {
      return NextResponse.redirect(new URL('/', request.url));
    }
  }
}
