Add rate limiting middleware to authentication endpoints:

```go
package main

import (
    "github.com/labstack/echo/v4"
    "github.com/labstack/echo/v4/middleware"
    "golang.org/x/time/rate"
    "time"
)

func main() {
    e := echo.New()

    // Create rate limiter for auth endpoints
    authRateLimiter := middleware.RateLimiterWithConfig(
        middleware.RateLimiterConfig{
            Skipper: middleware.DefaultSkipper,
            Store: middleware.NewRateLimiterMemoryStoreWithConfig(
                middleware.RateLimiterMemoryStoreConfig{
                    Rate:      rate.Limit(5),     // 5 requests
                    Burst:     10,                // burst of 10
                    ExpiresIn: 5 * time.Minute,   // per 5 minutes
                },
            ),
            IdentifierExtractor: func(ctx echo.Context) (string, error) {
                // Rate limit by IP + username combination
                ip := ctx.RealIP()
                username := ctx.FormValue("username")
                return ip + ":" + username, nil
            },
            ErrorHandler: func(context echo.Context, err error) error {
                return context.JSON(429, map[string]string{
                    "error": "Too many requests. Please try again later.",
                })
            },
            DenyHandler: func(context echo.Context, identifier string, err error) error {
                return context.JSON(429, map[string]string{
                    "error": "Rate limit exceeded.",
                })
            },
        },
    )

    // Apply to auth endpoints
    auth := e.Group("/auth")
    auth.Use(authRateLimiter)
    auth.POST("/login", loginHandler)
    auth.POST("/register", registerHandler)
    auth.POST("/password-reset", passwordResetHandler)
    auth.POST("/otp/verify", otpVerifyHandler)

    e.Start(":8080")
}
```

