  function xpath_quote(string $value): string {
      if (strpos($value, "'") === false) {
          return "'" . $value . "'";
      }
      if (strpos($value, '"') === false) {
          return '"' . $value . '"';
      }
      return "concat('" . str_replace("'", "',\"'\",'", $value) . "')";
  }

